from PIL import Image
from itertools import combinations
import string
im = Image.open('/app/image.png').convert('RGBA')
w,h = im.size
px = im.load()
def pixseq(order):
    if order=='row': return [(x,y) for y in range(h) for x in range(w)]
    if order=='col': return [(x,y) for x in range(w) for y in range(h)]
def decode(order, chans, rev, nbits=1):
    bits=[]
    for (x,y) in pixseq(order):
        p = px[x,y]
        for c in chans:
            for k in range(nbits):
                bits.append((p[c]>>k)&1)
    return bits
pr=set(string.printable)
def scan(bits, rev, tag):
    for off in range(8):
        out=bytearray()
        for i in range(off,len(bits)-7,8):
            b=bits[i:i+8]
            if rev: b=b[::-1]
            out.append(int(''.join(map(str,b)),2))
        s=''.join(chr(b) if chr(b) in pr else '.' for b in out)
        # find printable runs
        run=''
        for ch in s:
            if ch!='.':
                run+=ch
                if len(run)>=16:
                    print(tag, off, run[:60]); return
            else:
                run=''
for order in ['row','col']:
    for n in range(1,5):
        for chans in combinations(range(4),n):
            for rev in (False,True):
                bits=decode(order,chans,rev)
                scan(bits,rev,(order,chans,rev))
print('done')
